using System;using System.Globalization;using Rootborn.Game.Common;using Rootborn.Game.Localization;using Rootborn.Game.StudentLife;namespace Rootborn.UI.StudentLife{internal static class LocationStatePresentation{
public static string RecordTitle(LocationStateTodaySummarySaveData summary){if(summary==null)return string.Empty;if(summary.Hidden)return HiddenTitle;GameDataRegistryProvider.TryGet(out var registry);var definition=FindState(registry,summary.StateId);string key=definition!=null?definition.DisplayNameKey:summary.DisplayName;return string.IsNullOrEmpty(key)?UnknownTitle:GameText.Get(key);}
public static string RecordDetail(LocationStateTodaySummarySaveData summary){if(summary==null)return string.Empty;GameDataRegistryProvider.TryGet(out var registry);string location=Ui("life.location-state.record.location","마을","Town"),time=Ui("life.location-state.record.time","방문 시간","Visit time");if(registry!=null&&registry.Locations!=null)foreach(var d in registry.Locations)if(d!=null&&d.Id==summary.LocationId){location=GameText.Get(d.DisplayNameKey);break;}if(registry!=null&&registry.TimeSlots!=null)foreach(var d in registry.TimeSlots)if(d!=null&&d.Id==summary.TimeSlotId){time=GameText.Get(d.DisplayNameKey);break;}return summary.Day>0?string.Format(CultureInfo.CurrentCulture,Ui("life.location-state.record.detail","{0}일차 · {1} · {2}","Day {0} · {1} · {2}"),summary.Day,location,time):string.Format(CultureInfo.CurrentCulture,Ui("life.location-state.record.detail-no-day","장소 {0} · 시간 {1}","Place {0} · Time {1}"),location,time);}
public static string LiveTitle(LocationStateSummaryModel summary){if(summary.IsHidden)return HiddenTitle;string key=summary.PrimaryState!=null?summary.PrimaryState.DisplayNameKey:summary.DisplayName;return string.IsNullOrEmpty(key)?UnknownTitle:GameText.Get(key);}
public static string LiveDescription(LocationStateSummaryModel summary){if(summary.IsHidden)return string.Empty;return GameText.Get(summary.PrimaryState!=null?summary.PrimaryState.DescriptionKey:summary.Description);}
static LocationStateDefinition FindState(GameDataRegistry registry,string id){if(registry==null||registry.LocationStates==null||string.IsNullOrEmpty(id))return null;foreach(var definition in registry.LocationStates)if(definition!=null&&definition.Id==id)return definition;return null;}
static string HiddenTitle=>Ui("life.location-state.record.hidden","아직 밝혀지지 않은 기록","Undiscovered record");static string UnknownTitle=>Ui("life.location-state.record.unknown","방문한 장소의 변화","Place update");static string Ui(string key,string ko,string en){string text=GameText.Get(key);return text==key?(GameText.Language=="ko"?ko:en):text;}
}}
